import { Container, Graphics, Size, Text } from 'pixi.js';
import gsap from 'gsap';

import { Device } from '@game-studio/device';

import { AnimationSpeed, ICabinetConfig, ICabinetMessage } from '../../types/cabinet';
import { messageTextStyleRegular } from '../../layout/text-style';
import { killTweensIfAny } from '../../services/kill-tweens';

export abstract class SharedMessageView extends Container {
    protected textContainer: Container;
    protected messageText: Text;
    protected device: Device;
    protected maxDimensions: Size = { width: 0, height: 0 };
    protected isLeftHanded: boolean = false;

    private currentText: ICabinetMessage;
    protected viewMask: Graphics;

    private static readonly TWEEN_HEIGHT_MULTIPLIER: number = 1.5;
    private static readonly MAX_LINES: number = 2;
    private static readonly ANIMATION_SPEED: number = AnimationSpeed.messageText;
    protected static readonly MAX_SCALE: number = 0.9;

    private static sharedScale: number = SharedMessageView.MAX_SCALE;

    protected get isMobilePortrait(): boolean { return this.device.type.isMobile && this.device.orientation.isPortrait; }
    protected get animateOnTargetY(): number { return this.maxDimensions.height * 0.5; }

    public set isLeftHandedMode(isLeftHanded: boolean) { this.isLeftHanded = isLeftHanded; }

    constructor(device: Device) {
        super();

        this.device = device;

        this.createMask();
    }

    public static resetSharedScale(): void {
        SharedMessageView.sharedScale = SharedMessageView.MAX_SCALE;
    }

    public updateTextStyle(config: ICabinetConfig): void {
        const style = { ...messageTextStyleRegular };
        style.fill = config.text.message.colour;
        style.fontFamily = this.isMobilePortrait ? 'Wallop' : 'Wallop-Bold';
        style.fontSize = config.text.message.fontSize;

        this.messageText.style = style;
    }

    public updateLayoutStyle(): void {
        this.messageText.style.fontFamily = this.isMobilePortrait ? 'Wallop' : 'Wallop-Bold';
    }

    public setMaxDimensions(width: number, height: number): void {
        this.maxDimensions = { width, height };

        this.updateMask();
        this.setText(this.currentText, false);
    }

    public setText(text: ICabinetMessage, animate: boolean): void {
        killTweensIfAny(this.tweenTargets);

        this.currentText = text;

        let textToUpdateTo = this.device.orientation.isLandscape ? text?.landscape : text?.portrait;
        textToUpdateTo = this.formatMessageText(textToUpdateTo, text);

        if (animate && this.messageText.text !== textToUpdateTo) {
            this.animateOff().then(() => {
                this.updateText(textToUpdateTo);
                this.animateOn();
            });
        } else {
            this.updateText(textToUpdateTo);
        }
    }

    protected createMask(): void {
        this.viewMask = new Graphics();
    }

    protected updateMask(): void {
        if (this.maxDimensions.width === 0 || this.maxDimensions.height === 0 || !this.viewMask) { return; }

        const maskWidth = this.maskWidth;

        this.viewMask.clear();
        this.viewMask.moveTo(0, 0);
        this.viewMask.lineTo(maskWidth, 0);
        this.viewMask.lineTo(maskWidth, this.maxDimensions.height);
        this.viewMask.lineTo(0, this.maxDimensions.height);
        this.viewMask.closePath();
        this.viewMask.fill({ color: 0xffffff });
    }

    protected updateText(text: string): void {
        this.messageText.text = text;

        this.updateMessageScale();
    }

    private formatMessageText(baseText: string, textObj: ICabinetMessage): string {
        let textToUpdateTo = baseText ?? '';

        if (textObj?.amount) {
            textToUpdateTo += (this.device.orientation.isLandscape ? ' ' : '\n') + textObj.amount;
            const lines = textToUpdateTo.split(/\n/);

            if (lines.length > SharedMessageView.MAX_LINES) {
                textToUpdateTo = lines[0];
                for (let i = 1; i < lines.length; i++) {
                    if (i < 2) textToUpdateTo += '\n' + lines[i];
                    else textToUpdateTo += ' ' + lines[i];
                }
            }
        }

        return textToUpdateTo;
    }

    private addMask(): void {
        this.mask = this.viewMask;
        this.addChild(this.viewMask);
    }

    private removeMask(): void {
        this.mask = null;
        this.removeChild(this.viewMask);
    }

    protected createText(): void {
        this.textContainer = new Container();
        this.textContainer.name = 'text-container';

        this.addChild(this.textContainer);

        this.messageText = new Text('', messageTextStyleRegular);
        this.textContainer.addChild(this.messageText);
    }

    protected animateOff(): Promise<void> {
        return new Promise((resolve) => {
            this.addMask();

            gsap.to(this.tweenTargets, {
                duration: SharedMessageView.ANIMATION_SPEED,
                y: this.maxDimensions.height * SharedMessageView.TWEEN_HEIGHT_MULTIPLIER,
                onComplete: () => {
                    this.removeMask();

                    resolve();
                }
            });
        });
    }

    protected animateOn(): Promise<void> {
        return new Promise((resolve) => {
            this.addMask();

            gsap.fromTo(this.tweenTargets, { y: this.maxDimensions.height * -SharedMessageView.TWEEN_HEIGHT_MULTIPLIER }, {
                duration: SharedMessageView.ANIMATION_SPEED,
                y: this.animateOnTargetY,
                onComplete: () => {
                    this.removeMask();

                    resolve();
                }
            });
        });
    }

    /**
     * Calculates the scale factor to fit text within the available dimensions.
     * Updates and returns the shared scale so both views use the same (smallest) scale.
     */
    protected calculateTextScale(totalWidth: number, totalHeight: number): number {
        const widthScale = this.maxDimensions.width / totalWidth;
        const heightScale = this.maxDimensions.height / totalHeight;
        const calculatedScale = Math.min(widthScale, heightScale, SharedMessageView.MAX_SCALE);

        SharedMessageView.sharedScale = Math.min(SharedMessageView.sharedScale, calculatedScale);

        return SharedMessageView.sharedScale;
    }

    protected abstract updateMessageScale(): void;
    protected abstract get tweenTargets(): gsap.TweenTarget[];
    protected abstract get maskWidth(): number;
}